## File Uploads in REST APIs

## Option 1: Multipart Upload To Your Server

```typescript
// Client
const formData = new FormData();
formData.append('file', file);
formData.append('title', 'My Photo');
await fetch('/api/upload', { method: 'POST', body: formData });

// Next.js Route Handler
export async function POST(req: Request) {
  const formData = await req.formData();
  const file = formData.get('file') as File;

  // Validate
  if (!file) return Response.json({ error: 'No file' }, { status: 400 });
  if (file.size > 5 * 1024 * 1024) return Response.json({ error: 'Too large' }, { status: 413 });
  if (!['image/jpeg', 'image/png'].includes(file.type)) {
    return Response.json({ error: 'Invalid type' }, { status: 415 });
  }

  const buffer = Buffer.from(await file.arrayBuffer());
  // Upload to S3
  await s3.putObject({ Bucket: 'my-bucket', Key: `uploads/${crypto.randomUUID()}`, Body: buffer });
}
```

## Option 2: Presigned URLs (Recommended For Production)

```typescript
// Step 1: Client requests presigned URL
// GET /api/upload-url?filename=photo.jpg&type=image/jpeg
export async function GET(req: Request) {
  const { searchParams } = new URL(req.url);
  const key = `uploads/${crypto.randomUUID()}-${searchParams.get('filename')}`;

  const command = new PutObjectCommand({
    Bucket: process.env.S3_BUCKET!,
    Key: key,
    ContentType: searchParams.get('type') ?? 'application/octet-stream',
    ContentLengthRange: [1, 5 * 1024 * 1024], // max 5MB
  });

  const presignedUrl = await getSignedUrl(s3Client, command, { expiresIn: 300 });
  return Response.json({ presignedUrl, key });
}

// Step 2: Client uploads directly to S3 (no server bandwidth used)
await fetch(presignedUrl, { method: 'PUT', body: file, headers: { 'Content-Type': file.type } });

// Step 3: Client tells your API the upload is done
await fetch('/api/media', { method: 'POST', body: JSON.stringify({ key }) });
```

## API Request Validation with Zod

## Define Schema Once, Use Everywhere

```typescript
// schemas/question.ts
import { z } from 'zod';

export const CreateQuestionSchema = z.object({
  topic: z.enum(['react', 'typescript', 'nextjs', 'javascript']),
  level: z.number().int().min(1).max(5),
  question: z.string().min(10).max(500).trim(),
  answerGeneral: z.string().min(20).max(2000).trim(),
  tags: z.array(z.string().max(30)).max(5).optional(),
});

export type CreateQuestionInput = z.infer<typeof CreateQuestionSchema>;
// Type is derived from schema — single source of truth
```

## Route Handler With Validation

```typescript
import { CreateQuestionSchema } from '@/schemas/question';

export async function POST(req: Request) {
  let body: unknown;
  try {
    body = await req.json();
  } catch {
    return Response.json({ error: { code: 'INVALID_JSON', message: 'Request body must be valid JSON' } }, { status: 400 });
  }

  const parsed = CreateQuestionSchema.safeParse(body);
  if (!parsed.success) {
    return Response.json({
      error: {
        code: 'VALIDATION_ERROR',
        message: 'Invalid request body',
        details: parsed.error.errors.map(e => ({
          field: e.path.join('.'),
          message: e.message,
        })),
      },
    }, { status: 422 });
  }

  // parsed.data is fully typed — TypeScript knows the shape
  const question = await createQuestion(parsed.data);
  return Response.json(question, { status: 201 });
}
```

